from build import S,lesson as L,emit,source

def build():
 lessons=[
 L('select','SELECT expressions and aliases','SELECT produces result columns. AS names a result column without changing its value. A SELECT of constants needs no table; strings use single quotes.',
 S('SELECT ~${n}~;','${n}','0|NULL','SELECT returns the numeric literal as one row and one column.','0|NULL'),
 S("SELECT ~'${word}'~;",'${word}','NULL|Syntax error','Single quotes delimit a SQL string literal.','${word}|NULL'),
 S('SELECT ${n} ~AS~ size;','size','${n}|AS','AS labels the result column size.','FROM|WHERE','What is the result column name?'),
 S('SELECT ~${n}+${m}~;','${add}','${mul}|${n}${m}','The numeric expression is evaluated in the result.','${n}*${m}|${n}||${m}')),
 L('expressions','Arithmetic, text, and NULL','SQLite uses || for concatenation. Integer operands use integer division. NULL represents missing information; most arithmetic with NULL yields NULL.',
 S('SELECT ~${n}/${m}~;','${div}','${rem}|${mul}','With both operands integers, SQLite returns the integer quotient.','${n}%${m}|${n}*${m}'),
 S("SELECT '${word}' ~||~ '${word}';",'${joined}','0|${word}','The double-bar operator concatenates text.','+|='),
 S('SELECT ${n}+~NULL~;','NULL','${n}|0','Arithmetic propagates NULL instead of treating it as zero.','0|1'),
 S("SELECT ~length~('${word}');",'${length}','0|${n}','length counts the characters in this text.','upper|lower')),
 L('filter','Filtering with WHERE','WHERE retains rows whose condition is true; false and NULL are excluded. IS NULL tests missing values. Each table fixture is created afresh for its question.',
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (${n}), (0);\nSELECT size FROM item WHERE size ~>~ 0;','${n}','0|Both rows','The positive-size predicate excludes zero.','<|='),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (NULL), (${n});\nSELECT COUNT(*) FROM item WHERE size ~IS NULL~;','1','0|2','IS NULL recognizes the missing value.','= NULL|IS NOT NULL AND size<0'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (${n}), (0);\nSELECT size FROM item WHERE size ~BETWEEN~ 1 AND ${n};','${n}','0|No rows','BETWEEN includes both bounds.','NOT BETWEEN|IS'),
 S("CREATE TABLE item(name TEXT); INSERT INTO item VALUES ('${word}'), ('other');\nSELECT name FROM item WHERE name ~IN~ ('${word}');",'${word}','other|Both rows','IN tests membership in the listed values.','NOT IN|IS NOT')),
 L('order','Ordering and limiting results','Row order is unspecified without ORDER BY. ASC sorts upward; DESC downward. LIMIT caps rows; OFFSET skips rows after ordering.',
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (0), (${n});\nSELECT size FROM item ORDER BY size ~DESC~ LIMIT 1;','${n}','0|Either row','Descending order puts the larger value first.','ASC|COLLATE'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (${n}), (0);\nSELECT size FROM item ORDER BY size ~ASC~ LIMIT 1;','0','${n}|Either row','Ascending order puts zero first.','DESC|COLLATE'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (0), (${n});\nSELECT size FROM item ORDER BY size LIMIT 1 ~OFFSET 1~;','${n}','0|No rows','OFFSET skips the first sorted row.','OFFSET 0|OFFSET 2'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (${n}), (${n});\nSELECT ~DISTINCT~ size FROM item;','One row containing ${n}','Two rows containing ${n}|No rows','DISTINCT removes duplicate result rows.','ALL|*','How many rows are returned?')),
 L('schema','Tables, types, and constraints','CREATE TABLE declares columns and constraints. SQLite has dynamic typing and type affinity; do not assume another SQL dialect has identical coercion. NOT NULL and CHECK reject invalid rows.',
 S('CREATE TABLE item(size INTEGER ~NOT NULL~); INSERT INTO item VALUES (NULL);','Constraint error','Inserts zero|Inserts NULL','NOT NULL rejects a missing size.','DEFAULT 0|UNIQUE','What happens on INSERT?'),
 S('CREATE TABLE item(size INTEGER ~DEFAULT ${n}~); INSERT INTO item DEFAULT VALUES; SELECT size FROM item;','${n}','NULL|0','An omitted column receives its default expression.','DEFAULT 0|DEFAULT NULL'),
 S('CREATE TABLE item(size INTEGER ~CHECK(size>0)~); INSERT INTO item VALUES (0);','Constraint error','Inserts zero|Inserts NULL','CHECK rejects the row because size>0 is false.','CHECK(size>=0)|DEFAULT 1','What happens on INSERT?'),
 S("SELECT ~typeof~(${n});",'integer','text|real','typeof reports the SQLite storage class of this value.','quote|length')),
 L('writes','INSERT, UPDATE, and DELETE','INSERT creates rows. UPDATE and DELETE affect every matching row; omitting WHERE affects all rows. A statement runs against the current table state.',
 S('CREATE TABLE item(size INTEGER); ~INSERT~ INTO item VALUES (${n}); SELECT size FROM item;','${n}','NULL|No rows','INSERT adds one row with the supplied value.','UPDATE|DELETE'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (${n}); UPDATE item SET size=~size+1~; SELECT size FROM item;','${next}','${n}|0','UPDATE evaluates size+1 for the existing row.','size|0'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (0), (${n}); DELETE FROM item ~WHERE size=0~; SELECT size FROM item;','${n}','0|No rows','The WHERE clause restricts deletion to the zero row.','WHERE size=${n}|WHERE 1'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (0), (${n}); UPDATE item SET size=1; SELECT ~COUNT(*)~ FROM item WHERE size=1;','2','1|0','Without WHERE the update changes both rows.','SUM(size)+1|0')),
 L('aggregation','Aggregates and grouping','COUNT(*) counts rows; COUNT(column) excludes NULL. GROUP BY creates groups; HAVING filters aggregate groups after grouping.',
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (${n}), (NULL); SELECT ~COUNT(*)~ FROM item;','2','1|${n}','COUNT(*) counts both rows, including the one with NULL.','COUNT(size)|SUM(size)'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (${n}), (NULL); SELECT ~COUNT(size)~ FROM item;','1','2|${n}','COUNT(size) ignores NULL values.','COUNT(*)|SUM(size)'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (${n}), (${m}); SELECT ~SUM(size)~ FROM item;','${add}','${mul}|2','SUM combines the non-null numeric values.','COUNT(*)|MAX(size)'),
 S("CREATE TABLE item(tag TEXT); INSERT INTO item VALUES ('${word}'), ('${word}'), ('other'); SELECT tag FROM item GROUP BY tag ~HAVING~ COUNT(*)>1;",'${word}','other|Both tags','HAVING filters the already grouped rows by their aggregate count.','WHERE|ORDER BY')),
 L('joins','Keys and joins','JOIN combines rows according to a predicate. LEFT JOIN retains unmatched left rows with NULL right fields. Column qualification avoids ambiguity; joins may produce multiple rows per key.',
 S('CREATE TABLE a(id INTEGER); CREATE TABLE b(id INTEGER,size INTEGER); INSERT INTO a VALUES (1); INSERT INTO b VALUES (1,${n}); SELECT b.size FROM a JOIN b ~ON a.id=b.id~;','${n}','No rows|NULL','The equality predicate matches the common key.','ON a.id<>b.id|ON 0'),
 S('CREATE TABLE a(id INTEGER); CREATE TABLE b(id INTEGER); INSERT INTO a VALUES (1); SELECT b.id FROM a ~LEFT JOIN~ b ON a.id=b.id;','One row containing NULL','No rows|One row containing 1','LEFT JOIN preserves the unmatched left row.','INNER JOIN|CROSS JOIN','What result is returned?'),
 S('CREATE TABLE a(id INTEGER); CREATE TABLE b(id INTEGER); INSERT INTO a VALUES (1); INSERT INTO b VALUES (1),(1); SELECT ~COUNT(*)~ FROM a JOIN b ON a.id=b.id;','2','1|0','Both matching right rows produce joined rows.','COUNT(DISTINCT a.id)|0'),
 S('CREATE TABLE a(id INTEGER); CREATE TABLE b(id INTEGER); INSERT INTO a VALUES (1),(2); INSERT INTO b VALUES (3),(4); SELECT COUNT(*) FROM a ~CROSS JOIN~ b;','4','2|0','CROSS JOIN produces every pair of rows.','JOIN b ON a.id=b.id JOIN|LEFT JOIN')),
 L('subqueries','Subqueries and EXISTS','A subquery can supply a scalar or a set of rows. EXISTS tests whether any row exists, independent of its selected value. Qualify correlated references carefully.',
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (0),(${n}); SELECT size FROM item WHERE size=(SELECT ~MAX(size)~ FROM item);','${n}','0|Both rows','The scalar subquery supplies the maximum size.','MIN(size)|COUNT(*)'),
 S('SELECT ~EXISTS~(SELECT NULL);','1','0|NULL','EXISTS is true because the subquery produces one row, even though its value is NULL.','NOT EXISTS|length'),
 S('CREATE TABLE item(size INTEGER); SELECT ~EXISTS~(SELECT 1 FROM item);','0','1|NULL','EXISTS is false for an empty result.','NOT EXISTS|quote'),
 S('CREATE TABLE a(id INTEGER); CREATE TABLE b(id INTEGER); INSERT INTO a VALUES (1),(2); INSERT INTO b VALUES (2); SELECT a.id FROM a WHERE EXISTS(SELECT 1 FROM b WHERE ~b.id=a.id~);','2','1|Both rows','The correlated predicate tests whether each outer row has a matching inner key.','b.id<>a.id|1')),
 L('views','Views and common table expressions','A view stores a query definition. A nonrecursive WITH expression names a temporary query result for one statement. UNION removes duplicate rows; UNION ALL preserves them.',
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (${n}); CREATE ~VIEW~ sizes AS SELECT size FROM item; SELECT size FROM sizes;','${n}','NULL|No rows','A view exposes the result of its stored SELECT definition.','INDEX|TRIGGER'),
 S('~WITH~ sizes(x) AS (SELECT ${n}) SELECT x+1 FROM sizes;','${next}','${n}|0','WITH gives the subquery a name for this statement.','VIEW|TABLE'),
 S('SELECT ${n} ~UNION~ SELECT ${n};','One row containing ${n}','Two rows containing ${n}|No rows','UNION removes duplicate result rows.','UNION ALL|INTERSECT ALL','What result is returned?'),
 S('SELECT ${n} ~UNION ALL~ SELECT ${n};','Two rows containing ${n}','One row containing ${n}|No rows','UNION ALL preserves both result rows.','UNION|INTERSECT','What result is returned?')),
 L('transactions','Transactions and savepoints','BEGIN starts an explicit transaction; COMMIT makes its changes durable; ROLLBACK discards uncommitted changes. Savepoints support partial rollback inside a transaction.',
 S('CREATE TABLE item(size INTEGER); BEGIN; INSERT INTO item VALUES (${n}); ~ROLLBACK~; SELECT COUNT(*) FROM item;','0','1|${n}','ROLLBACK discards the insertion made inside the transaction.','COMMIT|END'),
 S('CREATE TABLE item(size INTEGER); BEGIN; INSERT INTO item VALUES (${n}); ~COMMIT~; SELECT size FROM item;','${n}','No rows|NULL','COMMIT retains the transaction changes.','ROLLBACK|ABORT'),
 S('CREATE TABLE item(size INTEGER); BEGIN; INSERT INTO item VALUES (${n}); SAVEPOINT second; INSERT INTO item VALUES (${m}); ~ROLLBACK TO second~; COMMIT; SELECT size FROM item;','${n}','${m}|No rows','Rolling back to the savepoint preserves the earlier insertion.','ROLLBACK|RELEASE second'),
 S('CREATE TABLE item(size INTEGER); BEGIN; INSERT INTO item VALUES (${n}); SAVEPOINT s; ~RELEASE s~; ROLLBACK; SELECT COUNT(*) FROM item;','0','1|${n}','Releasing a nested savepoint does not commit its enclosing transaction.','COMMIT|END')),
 L('integrity','Uniqueness, foreign keys, and conflict handling','Enable foreign-key enforcement on the connection. UNIQUE rejects duplicate non-null keys. SQLite ON CONFLICT can update an existing row. Constraint behavior is dialect-specific.',
 S('CREATE TABLE item(id INTEGER UNIQUE); INSERT INTO item VALUES (${n}); INSERT INTO item VALUES (~${n}~);','Unique constraint error','Two duplicate rows|Replaces the old row automatically','The duplicate non-null key violates UNIQUE.','0|NULL','What happens on the second INSERT?'),
 S('PRAGMA foreign_keys=~ON~; CREATE TABLE parent(id INTEGER PRIMARY KEY); CREATE TABLE child(pid INTEGER REFERENCES parent(id)); INSERT INTO child VALUES (${n});','Foreign-key constraint error','Inserts successfully|Creates the parent automatically','With enforcement on, the child key needs a matching parent row.','OFF|0','What happens when the parent table is empty?'),
 S('CREATE TABLE item(id INTEGER PRIMARY KEY,size INTEGER); INSERT INTO item VALUES (1,${n}); INSERT INTO item VALUES (1,${m}) ON CONFLICT(id) ~DO UPDATE SET size=excluded.size~; SELECT size FROM item;','${m}','${n}|Two rows','The upsert copies the attempted new size from excluded into the existing row.','DO NOTHING|DO UPDATE SET size=0'),
 S('CREATE TABLE item(id INTEGER UNIQUE); INSERT INTO item VALUES (1); INSERT INTO item VALUES (1) ON CONFLICT ~DO NOTHING~; SELECT COUNT(*) FROM item;','1','2|0','DO NOTHING skips the conflicting insertion.','DO UPDATE SET id=2|DO UPDATE SET id=NULL')),
 L('windows','Window functions and analytic reading','Window functions compute over related rows while retaining row identity. OVER defines partition and ordering. ROW_NUMBER numbers rows; an explicit frame controls a running aggregate.',
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (0),(${n}); SELECT size,~ROW_NUMBER()~ OVER(ORDER BY size) FROM item ORDER BY size;','0, 1; ${n}, 2','0, 0; ${n}, 1|One row only','ROW_NUMBER assigns one-based positions in the window order.','SUM(size)|COUNT(*)','Rows are shown as comma-separated columns, separated by semicolons. What is returned?'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (${n}),(${m}); SELECT COUNT(*) ~OVER()~ FROM item;','Two rows, each containing 2','One row containing 2|Two rows, each containing 1','An aggregate window retains each input row while counting the whole window.','|FILTER(WHERE size>0)','What result shape is returned?'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (1),(2); SELECT SUM(size) OVER(ORDER BY size ROWS BETWEEN ~UNBOUNDED PRECEDING~ AND CURRENT ROW) FROM item ORDER BY size;','1; 3','3; 3|1; 2','This frame includes every row from the start through the current row.','CURRENT ROW|1 FOLLOWING','What are the two running sums?'),
 S('CREATE TABLE item(size INTEGER); INSERT INTO item VALUES (1),(2); SELECT ~LAG(size)~ OVER(ORDER BY size) FROM item ORDER BY size;','NULL; 1','1; 2|2; NULL','LAG reads the preceding ordered row, or NULL when none exists.','LEAD(size)|FIRST_VALUE(size)','What are the two values?')),
 L('safequeries','Parameters, triggers, and NULL pitfalls','Bind values using the database API instead of concatenating SQL. Triggers respond to table changes. NULL uses three-valued logic; NOT IN with a NULL can yield unknown.',
 S('SELECT ~:size~ + 1;','${next}','${n}|NULL','The API binds the named parameter as the integer ${n}.',"':size'|NULL",'Assume :size is bound to integer ${n}. What is returned?'),
 S('SELECT ${n} ~NOT IN~ (0,NULL);','NULL','1|0','With no matching value and a NULL in the set, NOT IN has unknown truth value.','IS NULL OR ${n} IN|IS NOT','What value does this predicate produce?'),
 S('SELECT ~COALESCE~(NULL,${n},${m});','${n}','${m}|NULL','COALESCE returns the first non-null argument.','MAX|MIN'),
 S('CREATE TABLE item(size INTEGER); CREATE TABLE log(size INTEGER); CREATE TRIGGER audit AFTER INSERT ON item BEGIN INSERT INTO log VALUES (~NEW.size~); END; INSERT INTO item VALUES (${n}); SELECT size FROM log;','${n}','NULL|No rows','NEW refers to the inserted row within this trigger.','OLD.size|0'))]
 emit('sql','SQL (SQLite)','SQLite 3.35+; every question starts with a fresh in-memory database; result order is specified when relevant', [source('cs50sql','CS50 Introduction to Databases with SQL','https://cs50.harvard.edu/sql/'),source('sqlite','SQLite SQL language reference','https://www.sqlite.org/lang.html')],lessons)
